// The Queue app's session reads: the list, one session, its roster and its matches.
// Ports of packages/db/src/queue/{session-preparation,session-roster,match-queue,match-store}.ts. Reads only.
// Every club session in start order, or the one named; the counts are sessionSummaryDto's. request_formats is the
// Players can request list (an enum array, read as text). A session of another club is not returned.
func (q *Queries) ListQueueSessions(ctx context.Context, arg ListQueueSessionsParams) ([]ListQueueSessionsRow, error) {
	rows, err := q.db.Query(ctx, listQueueSessions, arg.ClubID, arg.SessionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListQueueSessionsRow
	for rows.Next() {
		var i ListQueueSessionsRow
		if err := rows.Scan(
			&i.ID,
			&i.ClubID,
			&i.Title,
			&i.Notes,
			&i.ScheduledStartAt,
			&i.ScheduledEndAt,
			&i.VenueID,
			&i.VenueName,
			&i.VenueAddress,
			&i.State,
			&i.InvalidReason,
			&i.CancelledAt,
			&i.CancelReason,
			&i.SessionMode,
			&i.AllowSingles,
			&i.AllowDoubles,
			&i.MinimumGames,
			&i.MinimumIsCalculated,
			&i.PlayersPerCourt,
			&i.ExpectedPlayers,
			&i.StartedAt,
			&i.FinalizedAt,
			&i.SeriesID,
			&i.PublicSlug,
			&i.AcceptJoinRequests,
			&i.AlwaysRequireRequest,
			&i.CourtFillMode,
			&i.RequestFormats,
			&i.RecordGames,
			&i.Revision,
			&i.QueueRevision,
			&i.HasStartTerm,
			&i.RosterCount,
			&i.PresentCount,
			&i.WaitlistCount,
			&i.CourtsInUse,
			&i.GamesPlayed,
			&i.QueuedCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

